"""경량 MJPEG HTTP 스트리밍 서버 (표준 라이브러리만 사용).

컨테이너처럼 GUI(cv2.imshow)가 없는 환경에서 처리 영상을 브라우저로 보기 위함.
노드가 매 프레임 JPEG 을 update() 로 밀어넣고, 브라우저는 http://<host>:<port>/ 접속.
"""

import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

_PAGE = (b"<html><head><title>person_detector</title></head>"
         b"<body style='margin:0;background:#000'>"
         b"<img src='/stream' style='width:100%'></body></html>")


class MjpegServer:
    def __init__(self, port=8080):
        self.port = port
        self._lock = threading.Lock()
        self._jpeg = None
        self._httpd = None

    def update(self, jpeg_bytes):
        with self._lock:
            self._jpeg = jpeg_bytes

    def start(self):
        server = self

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, *args):
                pass

            def do_GET(self):
                if self.path in ('/', '/index.html'):
                    self.send_response(200)
                    self.send_header('Content-Type', 'text/html')
                    self.end_headers()
                    self.wfile.write(_PAGE)
                    return
                if self.path != '/stream':
                    self.send_response(404)
                    self.end_headers()
                    return
                self.send_response(200)
                self.send_header('Content-Type',
                                 'multipart/x-mixed-replace; boundary=frame')
                self.end_headers()
                while True:
                    with server._lock:
                        jpeg = server._jpeg
                    if jpeg is not None:
                        try:
                            self.wfile.write(b'--frame\r\n'
                                             b'Content-Type: image/jpeg\r\n\r\n'
                                             + jpeg + b'\r\n')
                        except (BrokenPipeError, ConnectionResetError):
                            break
                    time.sleep(0.04)  # ~25fps

        self._httpd = ThreadingHTTPServer(('0.0.0.0', self.port), Handler)
        threading.Thread(target=self._httpd.serve_forever, daemon=True).start()

    def stop(self):
        if self._httpd is not None:
            self._httpd.shutdown()
            self._httpd = None
